	protected UpdateBOMCommand generateUpdateCommand() {
    UpdateBOMCommand command = new UpdateBOMCommand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),   new Date(),  null,  new HashSet<>(),  BOMStatus.values()[0] );

    return( command );
}
